             'object_write': 'oi-filled',                                     'mail_post': 'oi-filled',                                     'followers': 'oi-filled',                                     'remove_followers': 'oi-filled',                                     'webhook': 'oi-filled',                                 }[record.state.raw_value]\\" t-att-data-icon=\\"{                                     'code': 'code',                                     'object_create': 'add_box',                                     'object_copy': 'content_copy',                                     'object_write': 'edit',                                     'multi': 'format_list_bulleted',                                     'mail_post': 'mail',                                     'followers': 'person',                                     'remove_followers': 'person_remove',                                     'next_activity': 'schedule',                                     'sms': 'smartphone',                                     'webhook': 'send',                                     'whatsapp': 'oi_whatsapp',                                     'ai': 'wand_stars',                                 }[record.state.raw_value] || 'radio_button_unchecked'\\"/>\\n                            <i class=\\"oi text-warning px-2 m-0\\" data-icon=\\"warning\\" invisible=\\"not warning\\" t-att-title=\\"record.warning.raw_value\\"/>\\n                            <field name=\\"name\\" class=\\"text-truncate\\"/>\\n                            <button type=\\"delete\\" name=\\"delete\\" class=\\"btn oi oi-filled px-3 ms-auto\\" data-icon=\\"delete\\" title=\\"Eliminar acción\\"/>\\n                        </t>\\n                    </templates>\\n                </kanban>"}	<?xml version="1.0"?>\n<kanban default_order="sequence, name, id">\n                    <control>\n                        <create string="Add an action"/>\n                    </control>\n                    <field name="