220	16	\N	1	1	basic_layout	\N	web.basic_layout	qweb	web/views/report_templates.xml	primary	\N	{"en_US": "<t t-name=\\"web.basic_layout\\">\\n        <t t-call=\\"web.html_container\\">\\n            <t t-if=\\"not o\\" t-set=\\"o\\" t-value=\\"doc\\"/>\\n            <div class=\\"article\\" t-att-data-oe-model=\\"o and o._name\\" t-att-data-oe-id=\\"o and o.id\\" t-att-data-oe-lang=\\"o and o.env.context.get('lang')\\">\\n                <t t-out=\\"0\\"/>\\n            </div>\\n        </t>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="web.basic_layout">\n        <t t-call="web.html_container">\n            <t t-if="not o" t-set="o" t-value="doc"/>\n            <div class="article" t-att-data-oe-model="o and o._name" t-att-data-oe-id="o and o.id" t-att-data-oe-lang="o and o.env.context.get('lang')">\n                <t t-out="0"/>\n            </div>\n        </t>\n    </t>\n\n    	\N	f	t	2026-11-20 12:08:18.72865	2026-11-20 12:08:18.72865
