n\\" required=\\"1\\"/>\\n                            <field name=\\"font\\" string=\\"Texto\\" widget=\\"selection\\" required=\\"1\\"/>\\n                            <field name=\\"logo\\" string=\\"Logotipo\\" widget=\\"image\\" options=\\"{'size': [0, 50]}\\"/>\\n\\n                            <label for=\\"primary_color\\" string=\\"Colores\\"/>\\n                            <div class=\\"o_document_layout_colors d-flex align-items-end mb-4\\">\\n                                <field name=\\"primary_color\\" widget=\\"color\\" class=\\"w-auto m-0 me-1\\"/>\\n                                <field name=\\"secondary_color\\" widget=\\"color\\" class=\\"w-auto m-0\\"/>\\n                                <a class=\\"o_custom_colors btn btn-secondary btn-sm position-relative ms-2\\" role=\\"button\\" title=\\"Restablecer a colores de logotipo\\" invisible=\\"not custom_colors\\">\\n                                    <i class=\\"oi\\" data-icon=\\"redo\\"/> Restablecer\\n                                    <field name=\\"custom_colors\\" class=\\"position-absolute top-0 start-0 w-100 h-100 opacity-0\\" nolabel=\\"1\\"/>\\n                                </a>\\n                            </div>\\n\\n                            <field name=\\"company_details\\" string=\\"Dirección\\" options=\\"{'resizable': false}\\"/>\\n                            <field name=\\"report_header\\" string=\\"Lema\\" placeholder=\\"p. ej. Global Business Solutions\\" options=\\"{'resizable': false}\\"/>\\n                            <field name=\\"report_footer\\" placeholder=\\"Escribe tu teléfono, correo electrónico, cuenta bancaria, número de identificación fiscal...\\" string=\\"Pie de página\\" options=\\"{'resizable': false}\\"/>\\n                            <field name=\\"paperformat_id\\" widget=\\"selection\\" required=\\"1\\"/>\\n                        </group>\\n                        <div class=\\"o_preview\\">\\n                            <field name=\\"preview\\" widget=\\"iframe_wrapper\\" class=\\"preview_document_layout d-flex justify-content-center mb-0\\"/>\\n                        </div>\\n                    </group>\\n                    <footer>\\n                        <button string=\\"Continuar\\" class=\\"btn-primary\\" type=\\"object\\" name=\\"document_layout_save\\" data-hotkey=\\"q\\"/>\\n                        <button special=\\"cancel\\" data-hotkey=\\"x\\"/>\\n                    </footer>\\n                </form>"}	<?xml version="1.0"?>\n<form class="o_document_layout">\n                    <group>\n                        <group class="o_document_layout_company">\n                            <field name="company_id" invisible="1"/>\n                            <field name="external_report_layout_id" invisible="1"/>\n                            <field name="logo_primary_color" invisible="1"/>\n                            <field name="logo_secondary_color" invisible="1"/>\n                            <field name="report_layout_id" string="Layout" widget="badges_many2one" required="1"/>\n                            <field name="report_tables_id" string="Tables" widget="badges_selection" required="1"/>\n                            <field name="font" string="Text" widget="selection" required="1"/>\n                            <field name="logo" string="Logo" widget="image" options="{'size': [0, 50]}"/>\n\n                            <label for="primary_color" string="Colors"/>\n                            <div class="o_document_layout_colors d-flex align-items-end mb-4">\n                                <field name="primary_color" widget="color" class="w-auto m-0 me-1"/>\n                                <field name="secondary_color" widget="color" class="w-auto m-0"/>\n                                <a class="o_custom_colors btn btn-secondary btn-sm position-relative ms-2" role="button" title="Reset to logo colors" invisible="not custom_colors">\n                                    <i class="oi" data-icon="